5	// Renders a post's media. Images show the sample derivative; videos play
6	// the 720p h264 transcode produced by Hephaestus.
7	export function MediaViewer({ media }: Props) {
8	  if (media.kind === "video") {
9	    const src = derivativeUrl(media, "transcode-720p");
10	    return (
11	      <video controls preload="metadata" poster={derivativeUrl(media, "thumb")}>
12	        <source src={src} type="video/mp4" />
13	      </video>
14	    );
15	  }
16	  return <img src={derivativeUrl(media, "sample")} alt={media.title} />;
17	}
